#include "audio.h"
#include "config.h"
#include <stdint.h>
#include <string.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "driver/gpio.h"
#include "driver/i2s_std.h"
#include "esp_log.h"

#define FRAMES 256  // 16 ms per block at 16 kHz

static const char *TAG = "audio";

// Raw s16le mono @ PT_SAMPLE_RATE, generated by tools/make_ring.py.
extern const uint8_t ring_start[] asm("_binary_ring_pcm_start");
extern const uint8_t ring_end[] asm("_binary_ring_pcm_end");

static i2s_chan_handle_t s_tx, s_rx;
static volatile audio_mode_t s_mode = AUDIO_IDLE;
static volatile int s_mic_peak;

static void amps_set(bool earpiece, bool ringer)
{
#if PT_SINGLE_AMP
    gpio_set_level(PT_EARPIECE_AMP_SD_GPIO, earpiece || ringer);
#else
    gpio_set_level(PT_EARPIECE_AMP_SD_GPIO, earpiece);
    gpio_set_level(PT_RINGER_AMP_SD_GPIO, ringer);
#endif
}

static inline int16_t clip16(int32_t v)
{
    return v > 32767 ? 32767 : v < -32768 ? -32768 : v;
}

static void audio_task(void *arg)
{
    // Stereo frames of 32-bit slots: what the INMP441 needs, and the MAX98357A accepts.
    static int32_t rx[FRAMES * 2], tx[FRAMES * 2];
    static int16_t mono[FRAMES];
    const int16_t *ring = (const int16_t *)ring_start;
    const size_t ring_len = (ring_end - ring_start) / sizeof(int16_t);
    const size_t ring_period = (size_t)PT_SAMPLE_RATE * PT_RING_PERIOD_MS / 1000;

    audio_mode_t mode = AUDIO_IDLE;
    size_t ring_pos = 0;
    int32_t dc = 0;
    size_t n;

    for (;;) {
        audio_mode_t want = s_mode;
        if (want != mode) {
            mode = want;
            ring_pos = 0;
            amps_set(mode == AUDIO_LOOPBACK, mode == AUDIO_RING);
        }

        int gain = 0;
        memset(mono, 0, sizeof(mono));

        if (mode == AUDIO_RING) {
            gain = PT_RINGER_GAIN;
            for (int i = 0; i < FRAMES; i++) {
                if (ring_pos < ring_len) mono[i] = ring[ring_pos];
                if (++ring_pos >= ring_period) ring_pos = 0;
            }
        } else if (mode == AUDIO_LOOPBACK) {
            gain = PT_EARPIECE_GAIN;
            if (i2s_channel_read(s_rx, rx, sizeof(rx), &n, pdMS_TO_TICKS(100)) == ESP_OK) {
                int peak = s_mic_peak;
                for (int i = 0; i < FRAMES; i++) {
                    // Left slot, 24 significant bits MSB-aligned.
                    int32_t s = rx[i * 2] >> (16 - PT_MIC_SHIFT);
                    dc += (s - dc) >> 8;  // remove the mic's DC offset
                    mono[i] = clip16(s - dc);
                    int a = mono[i] < 0 ? -mono[i] : mono[i];
                    if (a > peak) peak = a;
                }
                s_mic_peak = peak;
            }
        }

        for (int i = 0; i < FRAMES; i++) {
            int32_t s = ((int32_t)mono[i] * gain / 256) * 65536;
            tx[i * 2] = tx[i * 2 + 1] = s;
        }
        // Blocks until the DMA has room, which paces this loop in real time.
        i2s_channel_write(s_tx, tx, sizeof(tx), &n, portMAX_DELAY);
    }
}

void audio_init(void)
{
    gpio_config_t sd = {
        .pin_bit_mask = (1ULL << PT_EARPIECE_AMP_SD_GPIO) | (1ULL << PT_RINGER_AMP_SD_GPIO),
        .mode = GPIO_MODE_OUTPUT,
    };
    gpio_config(&sd);
    gpio_set_level(PT_EARPIECE_AMP_SD_GPIO, 0);
    gpio_set_level(PT_RINGER_AMP_SD_GPIO, 0);

    i2s_chan_config_t chan = I2S_CHANNEL_DEFAULT_CONFIG(I2S_NUM_0, I2S_ROLE_MASTER);
    chan.auto_clear = true;  // underrun -> silence, not a repeated buffer
    ESP_ERROR_CHECK(i2s_new_channel(&chan, &s_tx, &s_rx));

    i2s_std_config_t std = {
        .clk_cfg = I2S_STD_CLK_DEFAULT_CONFIG(PT_SAMPLE_RATE),
        .slot_cfg = I2S_STD_PHILIPS_SLOT_DEFAULT_CONFIG(I2S_DATA_BIT_WIDTH_32BIT, I2S_SLOT_MODE_STEREO),
        .gpio_cfg = {
            .mclk = I2S_GPIO_UNUSED,
            .bclk = PT_I2S_BCLK_GPIO,
            .ws = PT_I2S_WS_GPIO,
            .dout = PT_I2S_DOUT_GPIO,
            .din = PT_I2S_DIN_GPIO,
        },
    };
    ESP_ERROR_CHECK(i2s_channel_init_std_mode(s_tx, &std));
    ESP_ERROR_CHECK(i2s_channel_init_std_mode(s_rx, &std));
    ESP_ERROR_CHECK(i2s_channel_enable(s_tx));
    ESP_ERROR_CHECK(i2s_channel_enable(s_rx));

    xTaskCreate(audio_task, "audio", 4096, NULL, 10, NULL);
    ESP_LOGI(TAG, "I2S up: %d Hz, ring tone %d bytes in flash", PT_SAMPLE_RATE, (int)(ring_end - ring_start));
}

void audio_set_mode(audio_mode_t mode) { s_mode = mode; }

int audio_take_mic_peak(void)
{
    int p = s_mic_peak;
    s_mic_peak = 0;
    return p;
}
